// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/agents/AgentToolsShot.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * Agent automation: turning on Allow app window control in Settings →
 * Connections → MCP integrations, ported from the app's McpMenu
 * (src/panels/McpMenu.tsx) and the confirmation it asks for (ConfirmDialog
 * and Modal in src/ui). That switch is what lets a connected agent work the
 * app: sessions, tiles, workspaces, editors and settings. The dialog answers
 * like the app: Allow window control turns the switch on, Cancel leaves it
 * off, and the switch asks again.
 */
import { useState } from "react";
import { Check, Copy, Download, RefreshCw, X } from "lucide-react";
import { SettingsScene } from "./parts";

// The agents McpMenu lists, from the server's framework configs (server/lib/mcp.js).
const FRAMEWORKS = ["Claude Code", "Codex", "OpenCode", "Cursor", "Windsurf", "Zed"];
// The bundled app's server script: its resources dir holds mcp/server.js (src-tauri/tauri.conf.json).
const SERVER_PATH = "/Applications/PzzaCode.app/Contents/Resources/mcp/server.js";

// The app's question (McpMenu's toggle).
const CONSENT = {
  title: "Allow app window control?",
  message:
    "Connected tools can read and control terminals, edit files, change settings and manage sessions in this app window. Only enable this for integrations you trust. Consequential actions still require local confirmation.",
  confirmLabel: "Allow window control",
};

/** The app's AsyncButton at rest: the icon in its reserved slot, then the label. */
function CheckNow() {
  return (
    <button type="button" className="btn btn-sm async-button" aria-busy={false}>
      <span className="async-button-icon" style={{ width: 14, height: 14 }} aria-hidden="true">
        <RefreshCw size={14} strokeWidth={2} />
      </span>
      Check now
    </button>
  );
}

export function AgentToolsShot() {
  const [enabled, setEnabled] = useState(false);
  const [asking, setAsking] = useState(true);
  const answer = (allow: boolean) => {
    if (allow) setEnabled(true);
    setAsking(false);
  };
  const toggle = () => {
    // Turning it off asks too in the app; the scene is about turning it on.
    if (enabled) setEnabled(false);
    else setAsking(true);
  };

  const confirm = asking ? (
    <div className="modal-backdrop pzza-portal confirmation-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) answer(false); }}>
      <div className="modal modal-sm" tabIndex={-1} role="alertdialog" aria-modal="true" aria-label={CONSENT.title} onMouseDown={(event) => event.stopPropagation()}>
        <div className="modal-head">
          <span className="modal-title">{CONSENT.title}</span>
          <button type="button" className="icon-btn" title="Close" aria-label="Close" onClick={() => answer(false)}>
            <span className="icon-inner">
              <X size={15} strokeWidth={1.9} />
            </span>
          </button>
        </div>
        <div className="modal-body">
          <p className="confirmation-message">{CONSENT.message}</p>
          <div className="modal-actions">
            <button type="button" className="btn" onClick={() => answer(false)}>
              Cancel
            </button>
            <button type="button" className="btn btn-accent" onClick={() => answer(true)}>
              {CONSENT.confirmLabel}
            </button>
          </div>
        </div>
      </div>
    </div>
  ) : null;

  return (
    <SettingsScene backdrop="palette" section="mcp" page="mcp" overlay={confirm}>
      <div className="settings-page mcp-settings">
        <div className="settings-row">
          <div className="settings-row-copy">
            <span>Allow app window control</span>
            <small>Control sessions, workspaces, editors, and app settings.</small>
          </div>
          <button
            type="button"
            className={`switch ${enabled ? "switch-on" : ""}`}
            role="switch"
            aria-label="Allow app window control"
            aria-checked={enabled}
            disabled={asking}
            onClick={toggle}
          >
            <span className="switch-knob" />
          </button>
        </div>
        <p className="set-note">
          File, device and session tools remain available when window control is off, except ending a session: the user confirms that in an app window with
          window control on.
        </p>
        <section className="settings-section" aria-label="Connection">
          <div className="settings-form">
            <label className="settings-field">
              <span>App SSH host</span>
              <input className="field-input" value="" placeholder="Local app (default)" spellCheck={false} readOnly />
              <small>Optional SSH target for an app on another device.</small>
            </label>
          </div>
        </section>
        <section className="settings-section" aria-label="Integration health">
          <div className="settings-row">
            <div className="settings-row-copy">
              <span>Automatic startup repairs</span>
              <small>Check installed server commands on each device every minute. Preserve configuration and private backups when a repair is needed.</small>
            </div>
            <CheckNow />
          </div>
          {["This Device", "Devbox"].map((device) => (
            <details key={device} className="settings-disclosure">
              <summary>{device} · Ready</summary>
            </details>
          ))}
        </section>
        <section className="settings-section" aria-label="Integrations">
          <h3 className="set-title">Integrations</h3>
          <div className="mcp-list">
            {FRAMEWORKS.map((label) => (
              <div key={label} className="settings-row mcp-row">
                <div className="settings-row-copy">
                  <span>{label}</span>
                </div>
                <div className="settings-actions">
                  {/* Add stays off until window control is allowed, as in the app. */}
                  <button type="button" className="btn btn-accent btn-sm async-button" aria-busy={false} disabled={!enabled}>
                    <span className="async-button-icon" style={{ width: 13, height: 13 }} aria-hidden="true">
                      <Download size={13} strokeWidth={2} />
                    </span>
                    Add
                  </button>
                  <button type="button" className="btn btn-sm" title="Copy configuration" aria-label={`Copy ${label} configuration`}>
                    <Copy size={13} strokeWidth={2} /> Copy
                  </button>
                </div>
              </div>
            ))}
          </div>
        </section>
        <p className="set-note mcp-path" title={SERVER_PATH}>
          <Check size={11} strokeWidth={2.5} /> server: {SERVER_PATH}
        </p>
      </div>
    </SettingsScene>
  );
}
